from scipy.optimize import minimize

def run_and_analyze(circuit, aer_sim, graph):
    # Transpile the circuit for the simulator
    transpiled = transpile(circuit, aer_sim)

    # Define initial parameters (one per parameter in the circuit)
    initial_params = [0.1] * circuit.num_parameters

    # Objective function: negative expectation (to maximize)
    def objective(params):
        # Create parameter binds
        param_dict = {circuit.parameters[i]: [params[i]] for i in range(len(params))}
        parameter_binds = [param_dict]

        # Run the circuit
        job = aer_sim.run(transpiled, parameter_binds=parameter_binds)
        counts = job.result().get_counts()

        # Compute expectation (use provided function)
        expect = compute_expectation(counts, graph)
        return -expect  # minimize negative => maximize

    # Optimize using COBYLA
    result = minimize(objective, initial_params, method='COBYLA', options={'maxiter': 100})
    optimal_params = result.x

    # Run circuit with optimal parameters to get final counts
    param_dict = {circuit.parameters[i]: [optimal_params[i]] for i in range(len(optimal_params))}
    parameter_binds = [param_dict]
    job = aer_sim.run(transpiled, parameter_binds=parameter_binds)
    final_counts = job.result().get_counts()

    # Sort bitstrings by frequency and take top two
    sorted_counts = sorted(final_counts.items(), key=lambda x: x[1], reverse=True)
    top_two = [bitstring for bitstring, _ in sorted_counts[:2]]
    return top_two"""
